from t8
where t8.a < (
select /*+ INDEX_LOOKUP_PUSHDOWN(t9, idx_a) */ sum(t9.b)
from t9 use index(idx_a)
where t9.a > t8.b
)
order by t8.a, t8.b;

select *
from t8
where t8.a < (
select /*+ INDEX_LOOKUP_PUSHDOWN(t9, idx_a) */ sum(t9.b)
from t9 use index(idx_a)
where t9.a > t8.b
)
order by t8.a, t8.b;

