select
(select ifnull(bit_xor(crc32(concat_ws('#', q.c0, q.c1, q.c2))), 0)
from (
select 85.11 as c0, t0.p1 as c1, '2024-01-02 12:28:00' as c2
from t0 right join t1 on (t0.k0 = t1.k0)
join t3 on (t0.k0 = t3.k0)
left join t2 on not not (t0.k0 = t2.k0)
left join t4 on (t0.k0 = t4.k0)
where (t0.k0 <=> t3.k0)
order by (t3.d0 - t2.k1) desc, t1.d0 desc
limit 5
) q) as chk_not_not,
(select ifnull(bit_xor(crc32(concat_ws('#', q.c0, q.c1, q.c2))), 0)
from (
select 85.11 as c0, t0.p1 as c1, '2024-01-02 12:28:00' as c2
from t0 right join t1 on (t0.k0 = t1.k0)
join t3 on (t0.k0 = t3.k0)
left join t2 on (t0.k0 = t2.k0)
left join t4 on (t0.k0 = t4.k0)
where (t0.k0 <=> t3.k0)
order by (t3.d0 - t2.k1) desc, t1.d0 desc
limit 5
) q) as chk_eq;

